#include <functional>
#include "AuraEngine.h"
#include <cstdio>
using namespace aura;
static std::vector<float> run(std::function<void(Engine&)> cfg,double secs){ Engine e; e.prepare(48000); for(int k=0;k<NP;k++) e.p[k]=0; e.p[oct]=-1; e.p[wave]=1; e.p[lvl]=0.75f; e.p[cut]=0.45f; e.p[pol]=4; e.p[vol]=1; e.p[s]=1; e.p[a]=0.002f; e.p[fs]=1; e.p[fa]=0.002f; e.p[e1]=e.p[e2]=e.p[e3]=1; e.p[l2r]=5; e.p[leg]=1; cfg(e); e.reset(); e.noteOn(45,100); std::vector<float> o((size_t)(secs*48000)); for(size_t i=0;i<o.size();i+=128) e.process(&o[i],std::min<size_t>(128,o.size()-i)); return o; }
static double harm(const std::vector<float>& o,double f){ size_t n=9600; double re=0,im=0; for(size_t i=o.size()-n;i<o.size();i++){ double t=(double)(i-(o.size()-n)); re+=o[i]*std::cos(6.2831853*f*t/48000); im+=o[i]*std::sin(6.2831853*f*t/48000);} return 2*std::hypot(re,im)/n; }
int main(){ struct C{const char* n; std::function<void(Engine&)> f;} cs[]={{"LP24",[](Engine&){}},{"BP12",[](Engine& e){e.p[fm]=1;e.p[pol]=2;}},{"BP24",[](Engine& e){e.p[fm]=1;}},{"HP12",[](Engine& e){e.p[fm]=2;e.p[pol]=2;}},{"HP24",[](Engine& e){e.p[fm]=2;}},{"ACID",[](Engine& e){e.p[fk]=1;}},{"ACID res",[](Engine& e){e.p[fk]=1;e.p[res]=0.8f;}},{"LFO2 vib",[](Engine& e){e.p[l2p]=0.5f;e.p[l2f]=0.5f;e.p[of]=0.3f;e.p[pwe]=0.5f;e.p[pe]=0.5f;e.p[wave]=2;}}};
  for(auto& c:cs){ auto o=run(c.f,1.0); double mx=0; bool bad=false; for(float x:o){ mx=std::max(mx,(double)std::fabs(x)); if(x!=x) bad=true; } printf("%-9s h1 %.3f h4 %.3f h10 %.3f h20 %.3f  pico %.2f %s\n",c.n,harm(o,55),harm(o,220),harm(o,550),harm(o,1100),mx,bad?"NaN!":""); } }
